insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20640')::uuid, md5('building-stahltwiete-20a-22761')::uuid, '20640', 'charmante-bueroflaeche-im-attraktiven-fabrikgebaeude-20640', 'Charmante Bürofläche im attraktiven Fabrikgebäude', 'Das charmante Fabrikgebäude im Hamburger Westen grenzt an die trendigen Szeneviertel Altona und Ottensen und zeichnet sich durch individuellen Charme und die verkehrsgünstige Lage …', 'Das charmante Fabrikgebäude im Hamburger Westen grenzt an die trendigen Szeneviertel Altona und Ottensen und zeichnet sich durch individuellen Charme und die verkehrsgünstige Lage aus. Vielseitige Einkaufsmöglichkeiten und diverse Restaurants und Cafés unterstreichen die Attraktivität dieses urbanen Standortes und sorgen für kulinarische Vielfalt. Das ehemalige Fabrikgebäude wurde aufwendig saniert und attraktive und individuelle Mieteinheiten geschaffen. Bei der angebotenen Fläche handelt es sich um eine der attraktivsten Einheiten auf dem Gelände, da dieses Büro über einen eigenen Vorhof verfügt und alle weiteren Nutzer andere Treppenhäuser nutzen. Ein guter Mix aus offenen, loftigen Bereichen, Meeting- und Rückzugsräumen, sowie einer großen Küche sorgt für ein angenehmes Arbeiten und gutes Teamgefühl. PKW- Stellplätze können nach Rücksprache direkt am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'erdgeschoss', 'stellplaetze']::text[], 88, 326, 'https://www.buerohamburg.de/objects/pdf/BHI_20640.pdf', null, 'filemaker', '20640') on conflict (id) do nothing;
