insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23506')::uuid, md5('building-wendenstrasse-4-6-20097')::uuid, '23506', 'flexibel-gestaltbare-flaechen-in-der-city-sued-23506', 'Flexibel gestaltbare Flächen in der City-Süd', 'Zwischen Heidenkampsweg und Amsinckstraße, unweit der S-Bahnstation Hammerbrook befindet sich dieses Bürogebäude. Das Gebäude verfügt über Personen- sowie Lastenaufzüge. Zur …', 'Zwischen Heidenkampsweg und Amsinckstraße, unweit der S-Bahnstation Hammerbrook befindet sich dieses Bürogebäude. Das Gebäude verfügt über Personen- sowie Lastenaufzüge. Zur Ausstattung der Bürofläche zählt u.a. Teppichbodenbelag, Rastereinbauleuchten, abgehängte Decken, außen liegender Sonnenschutz, sowie eine kleine Teeküche. Die Aufteilung kann nach den individuellen Wünschen des neuen Mieters erfolgen. PKW-Stellplätze können bei Bedarf angemietet werden. Die Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 179, 877, 'https://www.buerohamburg.de/objects/pdf/BHI_23506.pdf', null, 'filemaker', '23506') on conflict (id) do nothing;
