insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22688')::uuid, md5('building-besenbinderhof-41-20097')::uuid, '22688', 'stylische-art-d-co-bueroflaeche-im-neuen-geesthof-22688', 'Stylische Art-déco-Bürofläche im neuen Geesthof', 'Der 1927 erbaute Geesthof wurde bis Anfang 2021 aufwendig kernsaniert und zu modernen Büroflächen ausgebaut. Die Mönckebergstraße, mit zahlreichen Geschäften des täglichen Bedarfs …', 'Der 1927 erbaute Geesthof wurde bis Anfang 2021 aufwendig kernsaniert und zu modernen Büroflächen ausgebaut. Die Mönckebergstraße, mit zahlreichen Geschäften des täglichen Bedarfs und einer Vielzahl an Cafés und Restaurants, ist nach wenigen Fußminuten erreicht. Der nahe gelegene Hauptbahnhof sorgt für eine perfekte Anbindung an das öffentliche Verkehrsnetz. Die modernen Büroflächen werden über ein helles Foyer mit Personenaufzug erschlossen. Das Foyer als auch die Büroflächen werden im Art-déco-Stil hergerichtet. Hierzu zählen Teppich- und Vinylfußboden in Fischgrätenoptik, fast bodentiefe Fenster, elegante Beleuchtungssysteme in Form von Deckenspots und Stehleuchten, akustische Unterstützung durch Deckenlamellen mit Lichtbändern, teilweise innen liegender Sonnenschutz, 2,90-3,10 m hohe Decken, getrennte WC-Bereiche und eine moderne Pantry. PKW-Stellplätze können im Hof oder in umliegenden Parkhäusern angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 228, 1461, 'https://www.buerohamburg.de/objects/pdf/BHI_22688.pdf', null, 'filemaker', '22688') on conflict (id) do nothing;
