insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-11155')::uuid, md5('building-stephansplatz-2-6-20354')::uuid, '11155', 'exklusives-buero-im-repraesentativen-hansecontor-11155', 'Exklusives Büro im repräsentativen HanseContor', 'Das exklusive, 6-geschossige Geschäfts- und Bürohaus liegt direkt am Opernboulevard, der aufwändig umgestalteten Dammtorstraße zwischen Stephansplatz und Gänsemarkt. Die Vielzahl …', 'Das exklusive, 6-geschossige Geschäfts- und Bürohaus liegt direkt am Opernboulevard, der aufwändig umgestalteten Dammtorstraße zwischen Stephansplatz und Gänsemarkt. Die Vielzahl an Einkaufsmöglichkeiten und das große, gastronomische Angebot machen diese zentrale Ecklage im Innenstadtbereich so attraktiv. Die Staatsoper, die neue Spielbank und die Parkanlage Planten un Blomen liegen im direkten Umfeld. Diverse Buslinien und sowohl U- als auch S-Bahn befinden sich vor den Gebäuden. Die Flächen erschließen sich über ein repräsentatives Treppenhaus mit gläsernem Schnellaufzug. Die hochwertige Ausstattung umfasst u.a. Kühldecken, integrierter Grundbeleuchtung, Hohraumboden, Teppich- und Vinylboden, Schallisolierung und motorisch gesteuertem Sonnenschutz aus Alu-Raffstores. Diese Innenbilder sind beispielhaft gewählt. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. PKW Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_11155.pdf', null, 'filemaker', '11155') on conflict (id) do nothing;
