insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-10740')::uuid, md5('building-hans-henny-jahnn-weg-29-33-22085')::uuid, '10740', 'lichtdurchflutete-bueroflaeche-am-osterbekkanal-10740', 'Lichtdurchflutete Bürofläche am Osterbekkanal', 'Das repräsentative Bürohaus befindet sich im beliebten Stadtteil Uhlenhorst unmittelbar am schönen Osterbekkanal. Die Anbindung an den ÖPNV ist durch eine nahegelegene …', 'Das repräsentative Bürohaus befindet sich im beliebten Stadtteil Uhlenhorst unmittelbar am schönen Osterbekkanal. Die Anbindung an den ÖPNV ist durch eine nahegelegene Bushaltestelle gegeben. Diese ist ebenso wie diverse Geschäfte des täglichen Bedarfs und eine Vielzahl an Restaurants und Cafes im Mühlenkamp oder Hofweg fußläufig schnell zu erreichen. Die helle Bürofläche im Staffelgeschoss ist über den großzügigen Eingangsbereich mit Personenfahrstuhl zu erreichen. Zur derzeitigen Ausstattung zählen u.a. bodentiefe Fensterelemente, außenliegender Sonnenschutz, ein klimatisierter Serverraum sowie eine kleine Pantry und getrennte WC-Einheiten. Mehrere Büros sind mit einem kleinen Austritt zum einladenden Innenhof mit Wasserzugang bzw. zum Kanal ausgestattet. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können zusätzlich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze', 'wasserblick']::text[], 344, 1602, 'https://www.buerohamburg.de/objects/pdf/BHI_10740.pdf', null, 'filemaker', '10740') on conflict (id) do nothing;
