insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-12737')::uuid, md5('building-boschstrasse-23b-22761')::uuid, '12737', 'bezugsfertige-bueroflaeche-in-ruhiger-lage-von-bahrenfeld-12737', 'Bezugsfertige Bürofläche in ruhiger Lage von Bahrenfeld', 'Das moderne und repräsentative Bürogebäude befindet sich in zentraler und ruhiger Lage von Hamburg Bahrenfeld. Durch die unmittelbare Anbindung an die A7 und die fußläufig …', 'Das moderne und repräsentative Bürogebäude befindet sich in zentraler und ruhiger Lage von Hamburg Bahrenfeld. Durch die unmittelbare Anbindung an die A7 und die fußläufig erreichbare S-Bahn Station Bahrenfeld ist eine gute Erreichbarkeit gewährleistet. Die helle Bürofläche ist bereits ausgebaut und befindet sich in einem bezugsfertigen modernen Zustand. Hierzu zählen u.a. ein Teppichbodenbelag, teilweise Glastrennwände, eine bereits in Kabelkanälen verlegte Netzwerkverkabelung, integrierte Deckenbeleuchtung, eine großzügige Pantry sowie getrennte WC-Einheiten. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_12737.pdf', null, 'filemaker', '12737') on conflict (id) do nothing;
