  (md5('image-25385-2')::uuid, md5('property-25385')::uuid, 'https://www.buerohamburg.de/objects/images/25385/02_webBig.jpg', 'Hammerbrook: Moderne Bürofläche direkt am Fleet – Bild 2', 1, 'filemaker', '25385-02'),
