insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25633')::uuid, md5('building-paul-nevermann-platz-5-22765')::uuid, '25633', 'altona-modernes-buero-mit-einmaligem-blick-aus-dem-16-og-25633', 'Altona: Modernes Büro mit einmaligem Blick aus dem 16. OG', 'Der Kaiserhof befindet sich im Herzen Altonas. Der Bahnhof mit sämtlichen Fern- und Nahverkehrsanbindungen ist fußläufig schnell erreicht und sichert somit eine sehr gute …', 'Der Kaiserhof befindet sich im Herzen Altonas. Der Bahnhof mit sämtlichen Fern- und Nahverkehrsanbindungen ist fußläufig schnell erreicht und sichert somit eine sehr gute Anbindung an das Verkehrsnetz. Vielseitige Einkaufsmöglichkeiten und das lebendige Treiben in den vielen Cafés und Restaurants prägen diesen urbanen Stadtteil. Die helle Bürofläche erschließt sich über einen neu gestalteten Eingangsbereich mit vielen Glaselementen und drei Personenaufzügen. Die aktuelle Ausstattung umfasst Teppichbodenbelag, Akustikdecken, hochwertige Stehleuchten, elektrischer Sonnenschutz, eine Pantry und separate WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], 167, 344, 'https://www.buerohamburg.de/objects/pdf/BHI_25633.pdf', null, 'filemaker', '25633') on conflict (id) do nothing;
