insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24931')::uuid, md5('building-hoheluftchaussee-95-20253')::uuid, '24931', 'hoheluft-grosszuegige-bueroflaeche-in-ehemaliger-tabakfabrik-24931', 'Hoheluft: Großzügige Bürofläche in ehemaliger Tabakfabrik', 'Die ehemalige Tabakfabrik befindet sich in ruhiger Hinterhoflage an der lebendigen Hoheluftchaussee. Sie wurde 1902 erbaut und im Jahre 1984 umfangreich saniert. Die …', 'Die ehemalige Tabakfabrik befindet sich in ruhiger Hinterhoflage an der lebendigen Hoheluftchaussee. Sie wurde 1902 erbaut und im Jahre 1984 umfangreich saniert. Die U-Bahn-Station Hoheluftbrücke ist fußläufig schnell erreicht und sichert ebenso wie die Buslinie 5 einen sehr guten Anschluss an den ÖPNV. Vielseitige  Einkaufsmöglichkeiten und diverse Cafés, Bars und Restaurants prägen das lebendige Umfeld. Die lichtdurchflutete Bürofläche ist aktuell mit teilweise Parkettboden, EDV- Verkabelung, einer Pantry und separaten WC-Einheiten ausgestattet. Weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. Ein PKW-Stellplatz kann nach Rücksprache am Objekt dazu gemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 283, 345, 'https://www.buerohamburg.de/objects/pdf/BHI_24931.pdf', null, 'filemaker', '24931') on conflict (id) do nothing;
