insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-5960')::uuid, md5('building-rathausstrasse-7-20095')::uuid, '5960', 'effiziente-bueroflaeche-in-direkter-innenstatdtlage-5960', 'Effiziente Bürofläche in direkter Innenstatdtlage', 'Das angebotene Büro- und Geschäftsgebäude befindet sich in bester Citylage zwischen Mönckeberg- und Rathausstraße. Alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und …', 'Das angebotene Büro- und Geschäftsgebäude befindet sich in bester Citylage zwischen Mönckeberg- und Rathausstraße. Alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants prägen das lebendige Umfeld. Die U- und S-Bahnstationen Rathausmarkt und Jungfernstieg sowie diverse Buslinien sind nach wenigen Metern erreicht. Die Bürofläche wird über ein gepflegtes Foyer mit Personenaufzug und Paternoster erschlosen. Zur aktuellen Ausstattung zählen außen liegender elektrischen Sonnenschutz, Teppichfußboden, Beleuchtungssysteme, CAT-6-Verkabelung in Bodentanks, ein Serverraum, Glasschwerter, eine Pantry sowie getrennte WC-Einheiten. PKW-Stellplätze können in den umliegenden Parkhäusern angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_5960.pdf', null, 'filemaker', '5960') on conflict (id) do nothing;
