insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-14067')::uuid, md5('building-altstaedter-strasse-8-20095')::uuid, '14067', 'attraktive-ladenflaeche-im-sprinkenhof-mit-guter-sichtbarkeit-14067', 'Attraktive Ladenfläche im Sprinkenhof mit guter Sichtbarkeit', 'Das Hamburger Kontorhaus Sprinkenhof wurde von 1927 bis 1943 in drei Teilabschnitten  erbaut und steht heute unter Denkmalschutz. Die zentrale und doch ruhige Altstadtlage nahe …', 'Das Hamburger Kontorhaus Sprinkenhof wurde von 1927 bis 1943 in drei Teilabschnitten  erbaut und steht heute unter Denkmalschutz. Die zentrale und doch ruhige Altstadtlage nahe der belebten Einkaufsmeile Mönckebergstraße besticht mit einem vielseitigen gastronomischen Angebot und zahlreichen Cafés am Burchardplatz. Im Jahr 2002 wurde der Sprinkenhof umfangreich saniert. Die Ladenfläche im vorderen Bereich mit hohen Decken und sehr guter Sichtbarkeit ist durch einen Flur mit einer weiteren Fläche im hinteren Abschnitt verbunden, welche einen eigenen Eingang und eine Galerie hat, die über eine interne Treppe angeschlossen werden kann. Zur derzeitigen Ausstattung gehören u. a. Stehleuchten bzw. Deckenfluter, Laminat, getrennte WC-Einheiten und eine Pantry. Ausbau und Ausstattung erfolgen in Absprache mit dem zukünftigen Mieter. Der Mietpreis variiert je nach Ausstattungswunsch ab Euro 22,00 pro qm zzgl. Nebenkosten und MwSt.', 'laden-gastro', array['laden-gastro']::property_category[], 'laden', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['erdgeschoss']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_14067.pdf', null, 'filemaker', '14067') on conflict (id) do nothing;
