insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22275')::uuid, md5('building-gasstrasse-18-22761')::uuid, '22275', 'ruhige-bueroflaeche-in-begehrter-lage-22275', 'Ruhige Bürofläche in begehrter Lage', 'Das markante Bürogebäude befindet sich inmitten des lebendigen Gewerbeviertels in Bahrenfeld. Fußläufig erreichbar ist der Otto-von-Bahrenpark mit seinen zahlreichen …', 'Das markante Bürogebäude befindet sich inmitten des lebendigen Gewerbeviertels in Bahrenfeld. Fußläufig erreichbar ist der Otto-von-Bahrenpark mit seinen zahlreichen gastronomischen Angeboten sowie die S-Bahnstation Bahrenfeld. Das Objekt wurde von Innen sowie von Außen modernisiert. Zur Ausstattung der Fläche zählt unter anderem ein Teppichbodenbelag, teilweise Linolium, eine Pantry sowie getrennte WC-Einheiten. Die weitere Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können nach Rücksprache auf dem Gelände angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 349, 1228, 'https://www.buerohamburg.de/objects/pdf/BHI_22275.pdf', null, 'filemaker', '22275') on conflict (id) do nothing;
