insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-3765')::uuid, md5('building-schlossstrasse-8a-g-22041')::uuid, '3765', 'helle-bueroflaeche-in-bester-lage-von-wandsbek-3765', 'Helle Bürofläche in bester Lage von Wandsbek', 'Der Schlosshof Wandsbek besteht aus zwei Büroneubauten sowie einem vollständig modernisierten Altbau in zentraler Lage von Wandsbek. Sowohl die umliegende U-Bahn Station Wandsbek …', 'Der Schlosshof Wandsbek besteht aus zwei Büroneubauten sowie einem vollständig modernisierten Altbau in zentraler Lage von Wandsbek. Sowohl die umliegende U-Bahn Station Wandsbek Markt als auch der Horner Kreisel gewähren eine schnelle Verbindung in die Hamburger Innenstadt bzw. auf die Autobahnen. Geschäfte des täglichen Bedarfs sowie das Quarree befinden sich in unmittelbarer Umgebung. Die Bürofläche ist in einem gepflegten Zustand und erlaubt eine flexible Raumaufteilung. Weitere Wünsche des zukünftigen Mieters können berücksichtigt werden. Der Mietpreis variiert je nach Vertragslaufzeit, Ausstattung und Lage im Objekt. PKW-Stellplätze können nach Rücksprache zusätzlich in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 101, 602, 'https://www.buerohamburg.de/objects/pdf/BHI_3765.pdf', null, 'filemaker', '3765') on conflict (id) do nothing;
