insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25640')::uuid, md5('building-vorsetzen-32-39-20459')::uuid, '25640', 'boa-vista-bueroflaeche-im-portugiesenviertel-zur-untermiete-25640', 'Boa Vista: Bürofläche im Portugiesenviertel zur Untermiete', 'Das markante Bürogebäude befindet sich in bester Citylage direkt an der Elbe. Die U-Bahnstation Baumwall liegt nur wenige Fußminuten entfernt und sichert eine sehr gute Anbindung …', 'Das markante Bürogebäude befindet sich in bester Citylage direkt an der Elbe. Die U-Bahnstation Baumwall liegt nur wenige Fußminuten entfernt und sichert eine sehr gute Anbindung an das öffentliche Verkehrsnetz. Zahlreiche kleine Geschäfte und eine großes Angebot an Cafés und Restaurants im angrenzenden Portugiesenviertel unterstreichen die Attraktivität dieser lebendigen Lage. Die helle Bürofläche erschließt sich über ein modernes Foyer mit zwei Personenaufzügen. Die hochwertige Ausstattung umfasst Teppich- und Designfußboden, bodentiefe Fenster, Beleuchtungssysteme, Bodentanks, eine Kühlung über Betonkernaktivierung, Akustikelemente im Deckenbereich, außenliegenden, elektrischen Sonnenschutz, separate WC-Einheiten und eine moderne Pantry. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer ähnlichen im Objekt. PKW- Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['wasserblick']::text[], 204, 647, 'https://www.buerohamburg.de/objects/pdf/BHI_25640.pdf', null, 'filemaker', '25640') on conflict (id) do nothing;
