insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-3571')::uuid, md5('building-englische-planke-2-20459')::uuid, '3571', 'beeindruckende-aussicht-ueber-den-hamburger-hafen-3571', 'Beeindruckende Aussicht über den Hamburger Hafen', 'Das imposante Eckgebäude befindet sich in zentraler Citylage am Hamburger Michel und besticht durch seinen Mix aus historischer und moderner Architektur. Das Portugiesenviertel, …', 'Das imposante Eckgebäude befindet sich in zentraler Citylage am Hamburger Michel und besticht durch seinen Mix aus historischer und moderner Architektur. Das Portugiesenviertel, mit zahlreichen Cafés und Restaurants, als auch der Großneumarkt sind fußläufig schnell erreicht. Die nahe gelegenen U- und S-Bahnstationen St. Pauli und Stadthausbrücke sorgen für eine sehr gute Anbindung an den ÖPNV.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-3571-1')::uuid, md5('property-3571')::uuid, 'Mietfläche', 355, 23.5, null, 'filemaker', '3571-1') on conflict (id) do nothing;
