insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19613')::uuid, md5('building-wendenstrasse-8-12-20097')::uuid, '19613', 'das-hanse-atrium-in-der-city-sued-19613', 'Das Hanse-Atrium in der City-Süd', 'Das Hanse-Atrium befindet sich in äußerst verkehrsgünstiger Lage mitten in der City-Süd. Das Büro- und Geschäftsgebäude ist von weiteren Gebäuden umgeben, somit sind keine …', 'Das Hanse-Atrium befindet sich in äußerst verkehrsgünstiger Lage mitten in der City-Süd. Das Büro- und Geschäftsgebäude ist von weiteren Gebäuden umgeben, somit sind keine entstehende Verkehrs- und Bahngeräusche zu vernehmen. Zur aktuellen Büroausstattung gehören unter anderem außenliegender elektrischer Sonnenschutz , Hohlraumboden inkl. Bodentanks, teilweise bodentiefe Fensterelemente, Betonkernaktivierung, Beleuchtungssysteme, Bodenbeläge nach Mieterwunsch, getrennte WC-Einheiten sowie eine Pantry. Es stehen PKW-Stellplätze in der hauseigenen Tiefgarage zur Verfügung. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'erdgeschoss', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19613.pdf', null, 'filemaker', '19613') on conflict (id) do nothing;
