insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25004')::uuid, md5('building-mittelweg-161-20148')::uuid, '25004', 'exklusive-bueroflaeche-in-bester-lage-mit-balkon-25004', 'Exklusive Bürofläche in bester Lage mit Balkon', 'Das moderne Büro- und Geschäftsgebäude befindet sich in attraktiver Lage zwischen Außenalster und Rothenbaumchaussee, direkt am beliebten Mittelweg im Stadtteil Rotherbaum. …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in attraktiver Lage zwischen Außenalster und Rothenbaumchaussee, direkt am beliebten Mittelweg im Stadtteil Rotherbaum. Zahlreiche Einkaufsmöglichkeiten sowie diverse Cafés und Restaurants laden in der Umgebung zum Verweilen ein. Die Anbindung an den öffentlichen Nahverkehr ist durch die U-Bahnstation Hallerstraße, den S-Bahnhof Dammtor sowie die Buslinie 109 als sehr gut zu bezeichnen. Auch die Hamburger Innenstadt ist in wenigen Minuten erreichbar.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25004-1')::uuid, md5('property-25004')::uuid, 'Mietfläche', 367, 26.5, null, 'filemaker', '25004-1') on conflict (id) do nothing;
