  (md5('image-25004-2')::uuid, md5('property-25004')::uuid, 'https://www.buerohamburg.de/objects/images/25004/02_webBig.jpg', 'Exklusive Bürofläche in bester Lage mit Balkon – Bild 2', 1, 'filemaker', '25004-02'),
