insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25349')::uuid, md5('building-luruper-chaussee-125-22761')::uuid, '25349', 'loftige-bueroflaeche-im-historischen-kavallerie-quartier-25349', 'Loftige Bürofläche im historischen Kavallerie-Quartier', 'In einem etablierten Business-Quartier auf dem Gelände der ehemaligen Kavallerieschule in Hamburg-Bahrenfeld steht eine attraktive Bürofläche zur Vermietung. Die Einheit überzeugt …', 'In einem etablierten Business-Quartier auf dem Gelände der ehemaligen Kavallerieschule in Hamburg-Bahrenfeld steht eine attraktive Bürofläche zur Vermietung. Die Einheit überzeugt durch ihre große Fensterfront mit Blick in den Innenhof des Quartiers, die für eine helle und angenehme Arbeitsatmosphäre sorgt. Die durchdachte Flächenaufteilung kombiniert klassische Einzelbüros mit offenen Arbeitsbereichen und bietet damit ideale Voraussetzungen für unterschiedlichste Nutzungskonzepte.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25349-1')::uuid, md5('property-25349')::uuid, 'Mietfläche', 369, 13.5, null, 'filemaker', '25349-1') on conflict (id) do nothing;
