insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19847')::uuid, md5('building-karnapp-25-21079')::uuid, '19847', 'der-channel-tower-in-harburg-19847', 'Der Channel-Tower in Harburg', 'Der architektonisch sehr ansprechende Channel Tower befindet sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 und A7 sowie …', 'Der architektonisch sehr ansprechende Channel Tower befindet sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 und A7 sowie die Harburger Altstadt. Das Objekt verfügt über einen repräsentativen, lichtdurchfluteten Eingangsbereich. Die Grundausstattung der Bürofläche umfasst unter anderem eine Grundbeleuchtung, einen hochwertigen Bodenbelag, innenliegenden Blendschutz, ein EDV Raum,  eine funktionale Teeküche sowie separate sanitäre Anlagen. Die weitere Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Dazu steht den Mietern eine neu ausgebaute Dachfläche im 17. Obergeschoss, sowie kostenfreie Besprechungsräume zur Verfügung. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-19847-1')::uuid, md5('property-19847')::uuid, 'Mietfläche', 371, 17.5, null, 'filemaker', '19847-1') on conflict (id) do nothing;
