insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22674')::uuid, md5('building-erdkampsweg-43-22335')::uuid, '22674', 'ausbau-nach-mieterwunsch-praxisflaeche-im-erdkampsweg-22674', 'Ausbau nach Mieterwunsch: Praxisfläche im Erdkampsweg', 'Die angebotene Praxisfläche befindet sich in der lebendigen Einkaufsstraße Erdkampsweg in Fuhlsbüttel, unweit des Hamburger Flughafens. Die Anbindung an den ÖPNV ist durch diverse …', 'Die angebotene Praxisfläche befindet sich in der lebendigen Einkaufsstraße Erdkampsweg in Fuhlsbüttel, unweit des Hamburger Flughafens. Die Anbindung an den ÖPNV ist durch diverse Buslinien und den nahe gelegenen  U-Bahnhof sehr gut. Die vakante Gewerbefläche wird aktuell als Zahnarztpraxis genutzt und  in Absprache mit dem zukünftigen Mieter renoviert, aufgeteilt und ausgestattet. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK, MwSt.-frei', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['barrierefrei', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_22674.pdf', null, 'filemaker', '22674') on conflict (id) do nothing;
