insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25526')::uuid, md5('building-st-annenufer-2-20457')::uuid, '25526', 'attraktive-loft-bueroflaechen-in-der-speicherstadt-25526', 'Attraktive Loft-Büroflächen in der Speicherstadt', 'Der Speicher ist ein 1890–1892 errichteter historischer Kaffeespeicher im UNESCO-Weltkulturerbe der Speicherstadt, 2012 saniert und heute Sitz hochwertiger Büro- und …', 'Der Speicher ist ein 1890–1892 errichteter historischer Kaffeespeicher im UNESCO-Weltkulturerbe der Speicherstadt, 2012 saniert und heute Sitz hochwertiger Büro- und Showroomflächen sowie eines Cafés mit Rösterei und Museum. Die Lage ist absolut zentral und bestens angebunden: U1, U3 und U4 sind mit den Stationen Meßberg, Baumwall und Überseequartier ebenso in wenigen Gehminuten erreichbar wie mehrere Buslinien, und auch in die Innenstadt mit Mönckebergstraße und Rathausmarkt gelangt man zu Fuß in kürzester Zeit.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25526-1')::uuid, md5('property-25526')::uuid, 'Mietfläche', 372, 21, null, 'filemaker', '25526-1') on conflict (id) do nothing;
