insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21301')::uuid, md5('building-sportallee-6-22335')::uuid, '21301', 'helle-bueroflaeche-in-flughafennaehe-mit-blick-ins-gruene-21301', 'Helle Bürofläche in Flughafennähe mit Blick ins Grüne', 'Das flexibel nutzbare Gewerbeobjekt befindet sich in verkehrsgünstiger Lage in Flughafennähe. Das Autobahndreieck HH-Nordwest sichert eine gute Autobahnanbindung. Eine fußläufig …', 'Das flexibel nutzbare Gewerbeobjekt befindet sich in verkehrsgünstiger Lage in Flughafennähe. Das Autobahndreieck HH-Nordwest sichert eine gute Autobahnanbindung. Eine fußläufig schnell erreichte Bushaltestelle gewährleistet außerdem eine schnelle Anbindung zur U-Bahnstation Alsterdorf. Diverse gastronomische Angebot im näheren Umfeld sorgen für eine gute Mittagsversorgung. Die vakante Bürofläche erschließt sich über ein modernes Foyer mit Personenaufzug. Die aktuelle Ausstattung umfasst Teppichfußboden, Beleuchtungssysteme, EDV-Verkabelung in Fensterbrüstungskanälen, innen liegenden Sonnenschutz, separate WC-Einheiten und eine Pantry. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_21301.pdf', null, 'filemaker', '21301') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-21301-1')::uuid, md5('property-21301')::uuid, 'Mietfläche', 375, 9, null, 'filemaker', '21301-1') on conflict (id) do nothing;
