insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-13483')::uuid, md5('building-neue-grosse-bergstrasse-9-22765')::uuid, '13483', 'wirtschaftliche-praxisflaeche-im-repraesentativen-buerohaus-13483', 'Wirtschaftliche Praxisfläche im repräsentativen Bürohaus', 'Das Büro- und Geschäftsgebäude befindet sich unmittelbar an der Neuen Großen Bergstraße mit seinen zahlreichen Restaurants und Einkaufsmöglichkeiten des täglichen Bedarfs. Der …', 'Das Büro- und Geschäftsgebäude befindet sich unmittelbar an der Neuen Großen Bergstraße mit seinen zahlreichen Restaurants und Einkaufsmöglichkeiten des täglichen Bedarfs. Der Bahnhof Altona mit seinen zahlreichen Verbindungen sichert eine Anbindungen an den öffentlichen Nahverkehr und befindet sich nur wenige Gehminuten entfernt. Zur Ausstattung der hellen Bürofläche gehört unter anderem, ein Fußbodenbelag, eine Pantry sowie getrennte WC-Einheiten. Die hellen und funktionalen Mieteinheiten können in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden. Die Innenansichten sind beispielhaft ausgewählt. PKW-Stellplätze stehen im Umfeld zur Anmietung bereit.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_13483.pdf', null, 'filemaker', '13483') on conflict (id) do nothing;
