insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25567')::uuid, md5('building-bei-dem-neuen-krahn-2-20457')::uuid, '25567', 'moderne-bueroflaeche-gegenueber-der-speicherstadt-25567', 'Moderne Bürofläche gegenüber der Speicherstadt', 'Das 1956 erbaute Kontorhaus befindet sich gegenüber der historischen Speicherstadt. Im Jahr 2015 fanden umfangreiche Sanierungsmaßnahmen statt um das Gebäude auf den neusten Stand …', 'Das 1956 erbaute Kontorhaus befindet sich gegenüber der historischen Speicherstadt. Im Jahr 2015 fanden umfangreiche Sanierungsmaßnahmen statt um das Gebäude auf den neusten Stand der Technik zu bringen. Die U-Bahnstationen Baumwall und Rödingsmarkt liegen nur wenige Meter entfernt. Der Rathausmarkt mit allen Geschäften des täglichen Bedarfs sowie zahlreichen Cafés und Restaurants ist ebenfalls nach ca. 10 Fußminuten erreicht. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25567-1')::uuid, md5('property-25567')::uuid, 'Mietfläche', 380, 16.95, null, 'filemaker', '25567-1') on conflict (id) do nothing;
