insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19713')::uuid, md5('building-heidenkampsweg-44-46-20097')::uuid, '19713', 'effiziente-bueroflaechen-mit-hervorragender-anbindung-19713', 'Effiziente Büroflächen mit hervorragender Anbindung', 'Das 5 geschossige Büro- und Geschäftsgebäude befindet sich im Stadtteil Hammerbrook. Die Anbindung an den ÖPNV ist durch die U-/S-Bahn und diverse Buslinien gegeben. Der …', 'Das 5 geschossige Büro- und Geschäftsgebäude befindet sich im Stadtteil Hammerbrook. Die Anbindung an den ÖPNV ist durch die U-/S-Bahn und diverse Buslinien gegeben. Der Hauptbahnhof und die Autobahnen A1, A7, A24 sowie A255 sind schnell erreicht. Das Gebäude wurde vor einigen Jahren komplett erneuert und modernisiert. Die Mietflächen können in Absprache mit dem zukünftigen Mieter aufgeteilt werden. Zur Ausstattung zählen u.a. abgehängte Decken, integrierte Beleuchtungssysteme, Fensterbrüstungskanäle, Teppichboden, getrennte WC-Einheiten, eine Pantry und außenliegender Sonnenschutz. Diese Innenbilder sind beispielhaft gewählt. Ein Personenaufzug ist vorhanden. PKW-Stellplätze können auf dem Parkdeck oder in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19713.pdf', null, 'filemaker', '19713') on conflict (id) do nothing;
